{"command": "cd /workspace && python3 - <<'EOF'
import json, csv

awards = list(csv.DictReader(open('batch/awards.csv')))
hits = [json.loads(l) for l in open('batch/media_hits.jsonl')]
print("awards:", len(awards), "hits:", len(hits))
# hit tones by PI
for h in hits:
    print(h['hit_id'], h['pi_name'], '|', h['tone'])
# name-collision check: which award PIs share names with feed names
feed_names = {h['pi_name'] for h in hits}
for a in awards:
    if a['pi_name'] in feed_names:
        print("FEED-NAME-PI:", a['award_id'], a['pi_name'], a['institution'])
EOF"}
